def parse_duration(duration_str: str) -> int:
    """
    Convert a duration string like '1h30m45s' or '10m20s' into total seconds.

    Valid formats:
      - Single hour(s): '1h', '2h30m', '30m15s', etc.
      - Hours, minutes, seconds: '1h30m45s', '30m20s', '1h30m'

    Strategy:
      1. Strip whitespace
      2. Identify the last unit (e.g., 's' or 'm' or 'h')
      3. Extract numeric parts in that order
      4. Build total seconds
    """
    duration_str = duration_str.strip()
    if not duration_str:
        return 0

    # Get characters until the last unit letter (h/m/s)
    while len(duration_str) > 0 and not duration_str[-1] in 'hms':
        duration_str = duration_str[:-1]  # Remove last character

    # Now duration_str ends with the last unit
    end_letter = duration_str[-1]
    num_part = duration_str[:-1]  # Everything before the last letter

    # Extract all numeric substrings between the different units
    parts = []
    for unit in ['h', 'm', 's']:
        parts.extend([part for part in num_part.split(unit) if part]))

    # All parts are numeric strings
    if not parts:
        return 0

    # Combine parts with conversion factors
    total_seconds = 0
    for part in parts:
        val = int(part)
        if unit == 'h':
            total_seconds += val * 3600
        elif unit == 'm':
            total_seconds += val * 60
        elif unit == 's':
            total_seconds += val

    return total_seconds
